function chart(f){const data=[['Booked sales',f.bookedSales,''],['Earned revenue',f.earnedRevenue,''],['Recorded cost',f.recordedCost,'cost'],[f.actualProfit<0?'Actual loss':f.actualProfit===0?'Break-even':'Actual profit',f.actualProfit,f.actualProfit<0?'loss':'profit'],['Cash received',f.received,'']],max=Math.max(1,...data.map(d=>Math.abs(d[1])));return `<div class="chart" role="img" aria-label="${esc(data.map(d=>d[0]+': '+money(d[1])).join('; '))}. Signed amounts: losses extend left of zero; positive amounts extend right.">${data.map(([name,value,cl])=>`<div class="chart-row ${cl==='loss'?'loss-row':''}" data-series="${cl==='loss'||cl==='profit'?'actual-profit':esc(name.toLowerCase().replaceAll(' ','-'))}" data-sign="${value<0?'negative':value===0?'zero':'positive'}"><span>${name}</span><div class="chart-track"><div class="chart-bar ${cl}" style="width:${Math.abs(value)/max*50}%"></div><span class="chart-zero" aria-hidden="true"></span></div><span class="num ${value<0?'negative':''}">${money(value)}</span></div>`).join('')}</div><div class="chart-direction" aria-hidden="true"><span>Loss / negative</span><strong>0</strong><span>Positive amounts</span></div><p class="chart-foot">Bars start at zero: losses extend left; positive amounts extend right. Operational figures, net of tax. Actual profit includes all incurred costs, even before full delivery; cash is a separate series.</p>`;}
